mutation CreateNode($tableId: ID!, $content: String!, $title: String, $description: String) {
  createNode(input: {
    tableId: $tableId
    content: $content
    title: $title
    description: $description
  }) {
    success
    node {
      id
      content
      title
      description
      createdAt
      table {
        identifier
      }
    }
    errors {
      message
      code
    }
  }
}

query GetNode($id: ID!) {
  node(id: $id) {
    id
    content
    title
    description
    createdAt
    updatedAt
    table {
      id
      identifier
      description
    }
    attributes {
      id
      value
      attribute {
        identifier
        name
        type
      }
    }
    attributeCount
    relationCount
  }
}

query SearchNodes($tableId: ID!, $query: String!, $limit: Int = 10, $offset: Int = 0) {
  searchNodes(input: {
    tableId: $tableId
    query: $query
    limit: $limit
    offset: $offset
  }) {
    nodes {
      id
      content
      title
      description
      createdAt
      table {
        identifier
      }
    }
    totalCount
    hasNextPage
    hasPreviousPage
    query {
      originalQuery
      parsedConditions
    }
  }
}

mutation UpdateNode($id: ID!, $content: String, $title: String, $description: String) {
  updateNode(id: $id, input: {
    content: $content
    title: $title
    description: $description
  }) {
    success
    node {
      id
      content
      title
      description
      updatedAt
      table {
        identifier
      }
    }
    errors {
      message
      code
      field
    }
  }
}

mutation DeleteNode($id: ID!) {
  deleteNode(id: $id) {
    success
    errors {
      message
      code
    }
  }
}
